4390	    fn neighboring_activatable_entry(&self, current_position: usize) -> Option<ActivatableEntry> {
4391	        let entries = &self.contents.entries;
4392	        let is_header = |entry: &ListEntry| matches!(entry, ListEntry::ProjectHeader { .. });
4393	
4394	        let section_start = entries
4395	            .get(..current_position)?
4396	            .iter()
4397	            .rposition(is_header)
4398	            .map_or(0, |header| header + 1);
4399	        let section_end = entries
4400	            .get(current_position + 1..)?
4401	            .iter()
4402	            .position(is_header)
4403	            .map_or(entries.len(), |offset| current_position + 1 + offset);
4404	
4405	        for (start, end) in [(section_start, section_end), (0, entries.len())] {
4406	            let Some(before) = entries.get(start..current_position) else {
4407	                continue;
4408	            };
4409	            let Some(after) = entries.get(current_position + 1..end) else {
4410	                continue;
4411	            };
4412	
4413	            let Some(entry) = after
4414	                .iter()
4415	                .chain(before.iter().rev())
4416	                .find_map(ActivatableEntry::from_list_entry)
4417	            else {
4418	                continue;
4419	            };
4420	            return Some(entry);
4421	        }
4422	        None
4423	    }
